using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API using HttpClient.
/// Uses constructor injection — the SDK resolves DI services automatically
/// and does NOT expose them in the tool schema.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List all items from the API. Returns a JSON array of items.")]
    public async Task<string> ListItems(
        [Description("Maximum number of items to return (1-100)")] int limit = 20,
        [Description("Page offset for pagination (0-based)")] int offset = 0,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing items limit={Limit} offset={Offset}", limit, offset);
        var response = await httpClient.GetAsync($"/items?limit={limit}&offset={offset}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("Get a single item by its unique identifier.")]
    public async Task<string> GetItem(
        [Description("The unique identifier of the item to retrieve")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Getting item {Id}", id);
        var response = await httpClient.GetAsync($"/items/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool(Destructive = false, ReadOnly = false),
     Description("Create a new item. Returns the created item with its assigned ID.")]
    public async Task<string> CreateItem(
        [Description("Display name for the new item")] string name,
        [Description("Detailed description of the item")] string description,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating item {Name}", name);
        var payload = JsonSerializer.Serialize(new { name, description });
        var content = new StringContent(payload, Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync("/items", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool(Destructive = true),
     Description("Delete an item by its unique identifier. This action is irreversible.")]
    public async Task<string> DeleteItem(
        [Description("The unique identifier of the item to delete")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Deleting item {Id}", id);
        var response = await httpClient.DeleteAsync($"/items/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return $"Item {id} deleted successfully.";
    }
}

